 {"sec": "Initial assessment and circulation · p254", "page": 254, "q": "In an infant, the pulse is checked at the ___ artery.", "opts": ["carotid", "femoral", "brachial", "radial"], "ans": 2, "exp": "Pulse: brachial artery (infant); carotid or femoral (> 1 yr). (Book p254)", "type": "fill", "id": "PEDS-C53-050"},
 {"sec": "Initial assessment and circulation · p254", "page": 254, "q": "Beyond 1 year of age, the pulse is checked at the:", "opts": ["Radial artery at wrist", "Temporal artery on scalp", "Brachial artery (infant site)", "Carotid or femoral artery"], "ans": 3, "exp": "Carotid or femoral (> 1 yr). (Book p254)", "type": "mcq", "id": "PEDS-C53-051"},
 {"sec": "Initial assessment and circulation · p254", "page": 254, "q": "Breathing and pulse are checked simultaneously for < ___ sec.", "opts": ["10", "20", "30", "5"], "ans": 0, "exp": "Simultaneously checked for < 10 sec. (Book p254)", "type": "fill", "id": "PEDS-C53-052"},
 {"sec": "Initial assessment and circulation · p254", "page": 254, "q": "True or False — Pulse and breathing are checked one after the other for 30 seconds.", "opts": ["True", "False"], "ans": 1, "exp": "False — checked simultaneously for < 10 sec. (Book p254)", "type": "tf", "id": "PEDS-C53-053"},
 {"sec": "Initial assessment and circulation · p254", "page": 254, "q": "The site for chest compressions is the:", "opts": ["Left sternal edge", "Upper third of sternum", "Lower third of sternum", "Xiphisternum"], "ans": 2, "exp": "Site: lower 1/3rd of sternum. (Book p254)", "type": "mcq", "id": "PEDS-C53-054"},
