 {"sec": "Initial assessment and circulation · p254", "page": 254, "q": "Compression depth is:", "opts": ["One-third of the AP diameter of chest", "2 inches in all ages", "One-fourth of chest width", "Half the AP diameter"], "ans": 0, "exp": "Depth: 1/3rd of antero-posterior diameter of chest. (Book p254)", "type": "mcq", "id": "PEDS-C53-056"},
 {"sec": "Initial assessment and circulation · p254", "page": 254, "q": "Always allow full ___ to ensure filling of the heart.", "opts": ["compression", "recoil", "ventilation", "extension"], "ans": 1, "exp": "Always allow full recoil to ensure filling of heart. (Book p254)", "type": "fill", "id": "PEDS-C53-057"},
 {"sec": "Initial assessment and circulation · p254", "page": 254, "q": "The compression mantra in the chapter is:", "opts": ["Push light, push gently", "Push slow, push soft", "Push hard, push fast", "Push deep, push rarely"], "ans": 2, "exp": "Push hard, push fast. (Book p254)", "type": "mcq", "id": "PEDS-C53-058"},
 {"sec": "Initial assessment and circulation · p254", "page": 254, "q": "True or False — Full recoil between compressions ensures filling of the heart.", "opts": ["True", "False"], "ans": 0, "exp": "True — always allow full recoil to ensure filling of heart. (Book p254)", "type": "tf", "id": "PEDS-C53-059"},
 {"sec": "Initial assessment and circulation · p254", "page": 254, "q": "Match each assessment step with its detail:", "opts": ["A-3, B-1, C-4, D-2", "A-1, B-3, C-4, D-2", "A-3, B-1, C-2, D-4", "A-4, B-1, C-3, D-2"], "ans": 0, "exp": "Position, pulse sites and check duration are specified by age. Correct pairs: Position→Supine on a flat hard surface; Infant pulse→Brachial artery; Pulse beyond 1 year→Carotid or femoral; Breathing plus pulse check→Simultaneously for under 10 sec. (Book p254)", "type": "match", "pairs": [["Position", "Brachial artery"], ["Infant pulse", "Simultaneously for under 10 sec"], ["Pulse beyond 1 year", "Supine on a flat hard surface"], ["Breathing plus pulse check", "Carotid or femoral"]], "id": "PEDS-C53-060"},
 {"sec": "Initial assessment and circulation · p254", "page": 254, "q": "Odd one out (listed pulse sites):", "opts": ["Femoral", "Radial", "Brachial", "Carotid"], "ans": 1, "exp": "Radial is not listed; infant brachial, beyond 1 year carotid or femoral. (Book p254)", "type": "odd", "id": "PEDS-C53-061"},
 {"sec": "Initial assessment and circulation · p254", "page": 254, "q": "Which assessment sequence is correct here?", "opts": ["Femoral pulse check alone for 1 min, no positioning", "Skip scene safety, prone position, radial pulse for 30 sec", "Scene safety, supine hard surface, immobilise, brachial + breathing < 10 s", "Immediate intubation before any assessment steps"], "ans": 2, "exp": "Scene safety → supine flat hard → immobilise (RTA fracture) → infant brachial + breathing < 10 sec. (Book p254)", "type": "case", "stem": "An 8-month-old is unresponsive after a road traffic accident.", "id": "PEDS-C53-062"},
 {"sec": "Initial assessment and circulation · p254", "page": 254, "q": "How should compressions be given?", "opts": ["Xiphisternum at 140/min without any recoil", "Left chest at 80/min to any convenient depth", "Upper sternum at 60/min to half the AP diameter", "Lower sternum, 100–120/min, 1/3 depth, full recoil"], "ans": 3, "exp": "Lower 1/3 sternum, 100–120/min, 1/3 AP depth, full recoil — push hard, push fast. (Book p254)", "type": "case", "stem": "A 3-year-old in arrest needs chest compressions.", "id": "PEDS-C53-063"},
 {"sec": "Initial assessment and circulation · p254", "page": 254, "q": "True or False — Compression depth is one-third of the antero-posterior diameter of the chest.", "opts": ["True", "False"], "ans": 0, "exp": "True — depth 1/3rd of AP diameter of chest. (Book p254)", "type": "tf", "id": "PEDS-C53-064"},
 {"sec": "Airway, breathing and intubation · p254", "page": 254, "q": "The two listed airway manoeuvres in order are:", "opts": ["Jaw thrust, then head tilt–chin lift", "Head tilt–chin lift, then jaw thrust", "Chin lift, then cricoid pressure", "Jaw thrust, then bag-mask"], "ans": 1, "exp": "Airway: 1. Head tilt chin lift. 2. Jaw thrust. (Book p254)", "type": "mcq", "id": "PEDS-C53-065"},
 {"sec": "Airway, breathing and intubation · p254", "page": 254, "q": "The second airway manoeuvre is ___ thrust.", "opts": ["tongue", "chin", "jaw", "neck"], "ans": 2, "exp": "2. Jaw thrust (after head tilt chin lift). (Book p254)", "type": "fill", "id": "PEDS-C53-066"},
 {"sec": "Airway, breathing and intubation · p254", "page": 254, "q": "True or False — Jaw thrust is listed before head tilt–chin lift.", "opts": ["True", "False"], "ans": 1, "exp": "False — head tilt chin lift is first, jaw thrust second. (Book p254)", "type": "tf", "id": "PEDS-C53-067"},
 {"sec": "Airway, breathing and intubation · p254", "page": 254, "q": "Non-invasive breathing support is:", "opts": ["Bag-and-mask ventilation", "Cricothyrotomy", "Jet ventilation", "Endotracheal intubation"], "ans": 0, "exp": "Non-invasive: bag and mask ventilation. (Book p254)", "type": "mcq", "id": "PEDS-C53-068"},
 {"sec": "Airway, breathing and intubation · p254", "page": 254, "q": "Invasive breathing support is ___ intubation.", "opts": ["nasogastric", "endotracheal", "esophageal", "bronchial"], "ans": 1, "exp": "Invasive: endotracheal intubation. (Book p254)", "type": "fill", "id": "PEDS-C53-069"},
 {"sec": "Airway, breathing and intubation · p254", "page": 254, "q": "Endotracheal intubation is preferred in:", "opts": ["Awake children", "Outdoor arrests only", "In-hospital CPR and prolonged CPR", "Brief apneic spells only"], "ans": 2, "exp": "Preferred in: in-hospital CPR, prolonged CPR. (Book p254)", "type": "mcq", "id": "PEDS-C53-070"},
 {"sec": "Airway, breathing and intubation · p254", "page": 254, "q": "Odd one out (airway–breathing actions):", "opts": ["Head tilt–chin lift", "Jaw thrust", "Bag-and-mask ventilation", "Routine cricoid pressure"], "ans": 3, "exp": "Routine cricoid pressure is to be avoided; the rest are performed. (Book p254)", "type": "odd", "id": "PEDS-C53-071"},
 {"sec": "Airway, breathing and intubation · p254", "page": 254, "q": "The preferred type of ET tube is:", "opts": ["Cuffed", "Double-lumen", "Armoured", "Uncuffed"], "ans": 0, "exp": "Type of tube: cuffed. (Book p254)", "type": "mcq", "id": "PEDS-C53-072"},
 {"sec": "Airway, breathing and intubation · p254", "page": 254, "q": "ET tube size = (Age in years + 4) / ___.", "opts": ["3", "4", "5", "2"], "ans": 1, "exp": "Size of ET tube = Age (in yr) + 4 / 4. (Book p254)", "type": "fill", "id": "PEDS-C53-073"},
