 {"sec": "Airway, breathing and intubation · p254", "page": 254, "q": "Cuff pressure is kept below ___ cm of H2O.", "opts": ["30 to 35", "40 to 45", "10 to 15", "20 to 25"], "ans": 3, "exp": "Cuff pressure: < 20 to 25 cm of H2O (to prevent pressure necrosis). (Book p254)", "type": "fill", "id": "PEDS-C53-075"},
 {"sec": "Airway, breathing and intubation · p254", "page": 254, "q": "The cuff pressure limit prevents:", "opts": ["Pressure necrosis", "Vocal cord palsy", "Aspiration", "Tube blockage"], "ans": 0, "exp": "Cuff limit is to prevent pressure necrosis. (Book p254)", "type": "mcq", "id": "PEDS-C53-076"},
