 {"sec": "Airway, breathing and intubation · p254", "page": 254, "q": "The breathing rate during CPR is:", "opts": ["20–30/min", "40–60/min", "100–120/min", "8–10/min"], "ans": 0, "exp": "Rate of breathing: 20–30 breaths/min (1 breath every 2–3 sec). (Book p254)", "type": "mcq", "id": "PEDS-C53-080"},
